class Solution {
  public int[] countTasks(int[] tasks, int[] shifts) {
    int n = tasks.length;
    long[] prefix = new long[n + 1];
    for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + tasks[i];
    long total = prefix[n], progress = 0;
    int[] ans = new int[shifts.length];
    for (int s = 0; s < shifts.length; s++) {
      if (progress + shifts[s] >= total) {
        progress = 0;
        ans[s] = 0;
        continue;
      }
      progress += shifts[s];
      int lo = 0, hi = n;
      while (lo < hi) {
        int mid = (lo + hi + 1) >>> 1;
        if (prefix[mid] <= progress) lo = mid;
        else hi = mid - 1;
      }
      ans[s] = n - lo;
    }
    return ans;
  }
}
